from datetime import date, timedelta

class Loyalty:
    def __init__(self) -> None:
        self.purchases = {}
        self.redeemed = {}

    def purchase(self, customer: str, amount: float, day: date) -> int:
        """Record a purchase; returns the number of points earned."""
        if amount <= 0:
            raise ValueError("Purchase amount must be greater than zero")

        points = int(amount)

        if customer not in self.purchases:
            self.purchases[customer] = []

        self.purchases[customer].append((day, points))

        return points

    def balance(self, customer: str, day: date) -> int:
        """Points the customer can spend on the given day."""
        if customer not in self.purchases:
            return 0

        balance = 0
        for purchase_day, points in self.purchases[customer]:
            if purchase_day + timedelta(days=14) <= day:
                balance += points

        if customer not in self.redeemed:
            return balance

        for redeem_day, redeemed_points in self.redeemed[customer]:
            if redeem_day <= day:
                balance -= redeemed_points

        return balance

    def redeem(self, customer: str, points: int, day: date) -> None:
        """Redeem points."""
        if points % 100 != 0:
            raise ValueError("Points can only be redeemed in multiples of 100")

        available_balance = self.balance(customer, day)

        if points > available_balance:
            raise ValueError("Not enough points to redeem")

        if customer not in self.redeemed:
            self.redeemed[customer] = []

        self.redeemed[customer].append((day, points))
